namespace PdfKnead.EInvoice;

/// <summary>
/// Codes in plain text (KONZEPT.md, section 5.24, „Codes im Klartext“): the code lists of EN 16931 of the European Commission
/// (Zuordnung/codes.tsv, generated by Zuordnung/codelisten.py; CC BY 4.0) with their English names, and German names for the common codes
/// of invoice type, VAT category, payment means, units and the VAT point date code, written here; country and currency names in German and
/// English from Unicode CLDR (Zuordnung/laender.tsv, waehrungen.tsv; Unicode License v3). Which term uses which list follows
/// EN 16931 and the syntax bindings. A code no list knows stays a code — it is never guessed.
/// </summary>
public static class InvoiceCodes
{
    private static readonly Lazy<Dictionary<(string List, string Code), string>> Table = new(Load);

    /// <summary>The list of a term's value (its code list); null if the term holds no code.</summary>
    public static string? ListOf(string id) => id switch
    {
        "BT-3" => "1001",
        "BT-5" or "BT-6" => "Currency",
        "BT-8" => "2005",
        "BT-21" => "Text",
        "BT-40" or "BT-55" or "BT-69" or "BT-80" or "BT-159" => "Country",
        "BT-81" => "Payment",
        "BT-95" or "BT-102" or "BT-118" or "BT-151" => "5305",
        "BT-98" or "BT-140" => "Allowance",
        "BT-105" or "BT-145" => "Charge",
        "BT-121" => "VATEX",
        "BT-130" or "BT-150" => "Unit",
        _ => null,
    };

    /// <summary>The list of an attribute of a term's element (identifier schemes, electronic address schemes, MIME type, item classification).</summary>
    public static string? ListOf(string id, string attribute) => (id, attribute) switch
    {
        ("BT-29" or "BT-46" or "BT-60" or "BT-71" or "BT-157", "schemeID") => "ICD",
        ("BT-34" or "BT-49", "schemeID") => "EAS",
        ("BT-125", "mimeCode") => "MIME",
        ("BT-158", "listID") => "Item",
        (_, "unitCode") => "Unit",
        _ => null,
    };

    /// <summary>The name of a code in the current language: German where it is kept here, else the English name of the list; null if unknown.</summary>
    public static string? Name(string list, string? code)
    {
        if (string.IsNullOrWhiteSpace(code)) return null;
        code = code.Trim();
        if (Tr.Current.IsGerman && German.TryGetValue((list, code), out var de)) return de;
        if (list == "2005") return VatPointCodes.TryGetValue(code, out var bt8) ? (Tr.Current.IsGerman ? bt8.De : bt8.En) : null;
        if ((list switch { "Country" => Countries.Value, "Currency" => Currencies.Value, _ => null }) is { } cldr
            && cldr.TryGetValue(code, out var names))
        {
            var name = Tr.Current.IsGerman ? names.De : names.En;
            if (!string.IsNullOrEmpty(name)) return name;
        }
        return Table.Value.TryGetValue((list, code), out var en) ? en : null;
    }

    /// <summary>The name of the code a term holds; null if the term holds no code or the code is unknown.</summary>
    public static string? NameOf(InvoiceField field) => ListOf(field.Id) is { } list ? Name(list, field.Text) : null;

    /// <summary>Whether a code is in a list of the table, exactly as written (the code lists of EN 16931; the rules BR-CL ask it).</summary>
    public static bool Contains(string list, string code) => Table.Value.ContainsKey((list, code));

    /// <summary>How many codes the table has (tests).</summary>
    internal static int Count => Table.Value.Count;

    /// <summary>Country names in German and English from Unicode CLDR (Zuordnung/laender.tsv, generated by codelisten.py --cldr).</summary>
    private static readonly Lazy<Dictionary<string, (string De, string En)>> Countries = new(() => Names("laender.tsv"));

    /// <summary>Currency names in German and English from Unicode CLDR (Zuordnung/waehrungen.tsv, generated by codelisten.py --cldr).</summary>
    private static readonly Lazy<Dictionary<string, (string De, string En)>> Currencies = new(() => Names("waehrungen.tsv"));

    /// <summary>A table „code, German name, English name“ of the module's resources.</summary>
    private static Dictionary<string, (string De, string En)> Names(string resource)
    {
        var table = new Dictionary<string, (string, string)>(StringComparer.Ordinal);
        foreach (var line in InvoiceMap.Resource(resource))
        {
            if (line.Length == 0 || line[0] == '#') continue;
            var cols = line.Split('\t');
            if (cols.Length != 3) throw new InvalidDataException(resource + ": Zeile mit falscher Spaltenzahl");
            table[cols[0]] = (cols[1], cols[2]);
        }
        return table;
    }

    /// <summary>BT-8, the VAT point date code (a subset of UNTDID 2005 that the lists of the Commission do not carry).</summary>
    private static readonly Dictionary<string, (string De, string En)> VatPointCodes = new(StringComparer.Ordinal)
    {
        ["3"] = ("Ausstellungsdatum der Rechnung", "Invoice document issue date"),
        ["35"] = ("Tatsächliches Lieferdatum", "Delivery date, actual"),
        ["432"] = ("Zahlungsdatum", "Paid to date"),
    };

