        [("1001", "384")] = "Rechnungskorrektur",
        [("1001", "389")] = "Selbst ausgestellte Rechnung (Gutschriftverfahren)",
        [("1001", "261")] = "Selbst ausgestellte Gutschrift",
        [("1001", "326")] = "Teilrechnung",
        [("1001", "386")] = "Vorauszahlungsrechnung",
        [("1001", "751")] = "Rechnungsinformation für Buchungszwecke",
        [("1001", "875")] = "Abschlagsrechnung (Bauleistung)",
        [("1001", "876")] = "Teilschlussrechnung (Bauleistung)",
        [("1001", "877")] = "Schlussrechnung (Bauleistung)",
        [("Country", "1A")] = "Kosovo",            // codes of the list that CLDR names otherwise (XK) or not at all
        [("Country", "XI")] = "Nordirland",
        [("5305", "S")] = "Normalsatz",
        [("5305", "Z")] = "Nullsatz",
        [("5305", "E")] = "Steuerbefreit",
        [("5305", "AE")] = "Umkehrung der Steuerschuldnerschaft",
        [("5305", "K")] = "Innergemeinschaftliche Lieferung",
        [("5305", "G")] = "Ausfuhr außerhalb der EU",
        [("5305", "O")] = "Nicht steuerbar",
        [("5305", "L")] = "Kanarische Inseln (IGIC)",
        [("5305", "M")] = "Ceuta und Melilla (IPSI)",
        [("Payment", "1")] = "Nicht festgelegt",
        [("Payment", "10")] = "Barzahlung",
        [("Payment", "20")] = "Scheck",
        [("Payment", "30")] = "Überweisung",
        [("Payment", "42")] = "Zahlung auf ein Bankkonto",
        [("Payment", "48")] = "Bankkarte",
        [("Payment", "49")] = "Lastschrift",
        [("Payment", "54")] = "Kreditkarte",
        [("Payment", "55")] = "Debitkarte",
        [("Payment", "57")] = "Dauerauftrag",
        [("Payment", "58")] = "SEPA-Überweisung",
        [("Payment", "59")] = "SEPA-Lastschrift",
        [("Payment", "68")] = "Online-Zahlungsdienst",
        [("Payment", "97")] = "Verrechnung zwischen den Partnern",
