        [("Unit", "H87")] = "Stück",
        [("Unit", "C62")] = "Stück",
        [("Unit", "EA")] = "Stück",
        [("Unit", "XPP")] = "Stück",
        [("Unit", "HUR")] = "Stunde",
        [("Unit", "MIN")] = "Minute",
        [("Unit", "DAY")] = "Tag",
        [("Unit", "WEE")] = "Woche",
        [("Unit", "MON")] = "Monat",
        [("Unit", "ANN")] = "Jahr",
        [("Unit", "KGM")] = "Kilogramm",
        [("Unit", "GRM")] = "Gramm",
        [("Unit", "TNE")] = "Tonne",
        [("Unit", "MTR")] = "Meter",
        [("Unit", "KMT")] = "Kilometer",
        [("Unit", "MTK")] = "Quadratmeter",
        [("Unit", "MTQ")] = "Kubikmeter",
        [("Unit", "LTR")] = "Liter",
        [("Unit", "KWH")] = "Kilowattstunde",
        [("Unit", "P1")] = "Prozent",
        [("Unit", "LS")] = "Pauschale",
        [("Unit", "SET")] = "Satz",
        [("Unit", "PR")] = "Paar",
    };

    private static Dictionary<(string, string), string> Load()
    {
        var table = new Dictionary<(string, string), string>();
        foreach (var line in InvoiceMap.Resource("codes.tsv"))
        {
            if (line.Length == 0 || line[0] == '#') continue;
            var cols = line.Split('\t');
            if (cols.Length != 3) throw new InvalidDataException("codes.tsv: Zeile mit falscher Spaltenzahl");
            table[(cols[0], cols[1])] = cols[2];
        }
        return table;
    }
}
